import { expect, test } from "@playwright/test";

/**
 * Regressions from the independent site QA of 2026-09-25 (PR #4414):
 * the sticky nav let page text show through, the Codex command was 45%
 * hidden at 1440, and the Installation page broke the command mid-word.
 */
/**
 * The webServer is `next dev`, which compiles a route on its first request.
 * The first /docs route in this file used to pay that compile inside a 30s
 * test budget: run 39112334293 (job 117631083485) spent 40.0s and its
 * page.goto ended in ERR_ABORTED when the test timed out, and run 39121361933
 * (attempt 1) timed out on the Close Banner click after the same goto. Both
 * retries passed in 14.8s and 4.2s once the route was warm (#4800).
 */
const DOCS_ROUTES = ["/docs/foundations/overview", "/docs/getting-started/installation"];

test.describe("Site QA", () => {
	test.use({ viewport: { width: 1440, height: 900 } });

	test.beforeAll(async ({ playwright }, testInfo) => {
		// Wait for each docs route to compile, in its own budget, so no test
		// measures the compile. A 200 means the route is built; the tests
		// still load the page themselves.
		test.setTimeout(180_000);
		const api = await playwright.request.newContext({ baseURL: testInfo.project.use.baseURL });
		try {
			for (const route of DOCS_ROUTES) {
				const res = await api.get(route, { timeout: 170_000 });
				expect(res.status(), `warm ${route}`).toBe(200);
			}
		} finally {
			await api.dispose();
		}
	});

	for (const path of ["/", "/changelog", "/community"]) {
		test(`sticky nav surface is opaque mid-scroll on ${path}`, async ({ page }) => {
			await page.goto(path);
			await page.mouse.wheel(0, 700);
			await expect
				.poll(() => page.evaluate(() => window.scrollY))
				.toBeGreaterThan(300);
			const alpha = await page.evaluate(() => {
				const surface = document.querySelector("#nd-nav > div");
				if (!surface) return -1;
				const probe = document.createElement("canvas").getContext("2d");
				if (!probe) return -1;
				// Resolve any color syntax (oklab, rgb) to rgba through a 1px paint.
				probe.fillStyle = getComputedStyle(surface).backgroundColor;
				probe.fillRect(0, 0, 1, 1);
				return probe.getImageData(0, 0, 1, 1).data[3];
			});
			expect(alpha).toBe(255);
		});
	}

	test("a dead link says so in its title", async ({ page }) => {
		// The 404 carried the home title in the tab and history (dogfood 007).
		await page.goto("/no-such-page-site-qa");
		await expect(page).toHaveTitle(/^Page not found/);
	});

	for (const path of ["/changelog", "/community"]) {
		test(`search is visible in the nav on ${path} at 1440`, async ({ page }) => {
			// The only desktop search control was hidden; ⌘K was the only way in (dogfood 006).
			await page.goto(path);
			const search = page.locator("#nd-nav").getByRole("button", { name: /^Search/ }).first();
			await expect(search).toBeVisible();
		});
	}

	test("a returning visitor who closed the banner gets no stale offset", async ({ page }) => {
		// The dotted banner id made fumadocs' pre-hydration hide rule an invalid
		// selector, and the offset was measured before the banner was removed,
		// so the docs sidebar kept a ~48px gap until the first scroll (review).
		await page.goto(DOCS_ROUTES[0]);
		await page.getByRole("button", { name: "Close Banner" }).click();
		await page.reload({ waitUntil: "load" });
		// Past hydration (fumadocs removes the dismissed banner in an effect), with
		// no scroll, which is when the stale offset used to show. Wait for the
		// banner to leave, then poll the offset: the stale offset held until the
		// first scroll, so it still fails once the poll times out.
		await expect(page.getByRole("region", { name: "Release announcement" })).toHaveCount(0);
		await expect
			.poll(
				() =>
					page.evaluate(() =>
						getComputedStyle(document.documentElement).getPropertyValue("--fd-banner-height").trim(),
					),
				{ message: "--fd-banner-height after a dismissed banner" },
			)
			.toMatch(/^(0px)?$/);
		expect(await page.evaluate(() => window.scrollY)).toBe(0);
	});

	test("the release banner sits in a named landmark", async ({ page }) => {
		// axe "region" fired on every route for the unlandmarked banner (QA #22).
		await page.goto("/");
		const banner = page.getByRole("region", { name: "Release announcement" });
		await expect(banner).toBeVisible();
		await expect(banner).toContainText("skills");
	});

	test("the whole Codex command is visible at 1440", async ({ page }) => {
		await page.goto("/?host=codex");
		const command = page.locator('[aria-label="Codex install command"]');
		await expect(command).toContainText("--sparse plugins/ork-codex");
		// Nothing may sit past the right edge of the command area, whether it
		// scrolls (the old markup) or clips.
		const clipped = await command.evaluate((el) => {
			const edge = el.getBoundingClientRect().right;
			const range = document.createRange();
			range.selectNodeContents(el);
			const textRight = Math.max(...[...range.getClientRects()].map((r) => r.right));
			return el.scrollWidth > el.clientWidth + 1 || textRight > edge + 0.5;
		});
		expect(clipped).toBe(false);
	});

	test("the Installation page never breaks a command mid-word", async ({ page }) => {
		await page.goto(DOCS_ROUTES[1]);
		await expect(page.getByText("Click a chip")).toHaveCount(0);
		const card = page.getByRole("button", { name: /^Copy claude plugin marketplace add/ }).first();
		await expect(card).toBeVisible();
		expect(await card.evaluate(tokensSplitAcrossLines)).toEqual([]);
		// And no card's command runs past its card, at every width where the
		// grid changes shape (Devin ran 95px into the next card at 1440; Codex
		// clipped between 768 and 850px).
		for (const width of [360, 390, 768, 800, 820, 850, 1024, 1280, 1440]) {
			await page.setViewportSize({ width, height: 900 });
			// setViewportSize resolves when the browser resized, not when the page
			// settled, so a read in the same tick can see the previous width's
			// layout (CI run 39140558431: every card "overflowed" at 360, the
			// identical tree passed minutes later; suspected cause, not reproduced). Wait for fonts and two frames, then poll: a real
			// overflow is stable and still fails once the poll times out.
			await page.evaluate(
				() =>
					document.fonts.ready.then(
						() =>
							new Promise<void>((done) =>
								requestAnimationFrame(() => requestAnimationFrame(() => done())),
							),
					),
			);
			await expect
				.poll(
					() =>
						page.evaluate(() =>
							[...document.querySelectorAll("button[aria-label^='Copy ']")]
								.filter((b) => {
									const edge = b.getBoundingClientRect().right;
									const range = document.createRange();
									range.selectNodeContents(b);
									return Math.max(...[...range.getClientRects()].map((r) => r.right)) > edge + 0.5;
								})
								.map((b) => b.getAttribute("aria-label")?.slice(0, 40)),
						),
					{ message: `at ${width}px`, timeout: 5_000 },
				)
				.toEqual([]);
		}
	});

	test.describe("phone", () => {
		test.use({ viewport: { width: 390, height: 844 } });

		test("the Codex command wraps only at spaces at 390", async ({ page }) => {
			await page.goto("/?host=codex");
			const command = page.locator('[aria-label="Codex install command"]');
			await expect(command).toContainText("ork-codex@orchestkit-codex");
			expect(await command.evaluate(tokensSplitAcrossLines)).toEqual([]);
		});

		// Every host, because Devin's 406px git URL was clipped at 390 while the
		// other seven fit (gate NEW-1). Nothing may reach past the command box.
		for (const host of ["claude", "cursor", "codex", "devin", "opencode", "muse", "pi", "agy"]) {
			test(`the ${host} command stays inside its box at 390`, async ({ page }) => {
				await page.goto(`/?host=${host}`);
				const box = page.locator("[data-hero-install]");
				await expect(box).toBeVisible();
				const past = await box.evaluate((el) => {
					const edge = el.getBoundingClientRect().right;
					const range = document.createRange();
					range.selectNodeContents(el);
					return Math.max(...[...range.getClientRects()].map((r) => r.right)) - edge;
				});
				expect(past).toBeLessThanOrEqual(0.5);
			});
		}
	});
});

/** Segments (see below) whose glyphs land on more than one line. */
function tokensSplitAcrossLines(el: Element): string[] {
	const walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
	const nodes: { node: Text; start: number }[] = [];
	let text = "";
	let block: Element | null = null;
	while (walker.nextNode()) {
		const node = walker.currentNode as Text;
		// Each command line is its own div; never join the end of one line
		// to the start of the next into one fake token.
		const own = node.parentElement?.closest("div") ?? null;
		if (block && own !== block) text += "\n";
		block = own;
		nodes.push({ node, start: text.length });
		text += node.data;
	}
	// Map a text offset back to its node, so a token spread over several
	// nodes (one span per token) is measured as one range.
	const at = (pos: number) => {
		const hit = [...nodes].reverse().find((n) => n.start <= pos) ?? nodes[0];
		return { node: hit.node, offset: Math.min(pos - hit.start, hit.node.length) };
	};
	const broken: string[] = [];
	// A segment is a run of non-space up to and including a "/", "#" or "@":
	// long URLs and package refs may wrap there on purpose, never inside a
	// segment or at a hyphen.
	for (const m of text.matchAll(/[^\s/#@]+[/#@]?|[/#@]/g)) {
		const range = document.createRange();
		const a = at(m.index ?? 0);
		const b = at((m.index ?? 0) + m[0].length);
		range.setStart(a.node, a.offset);
		range.setEnd(b.node, b.offset);
		const lines = new Set([...range.getClientRects()].filter((r) => r.width > 0).map((r) => Math.round(r.top)));
		if (lines.size > 1) broken.push(m[0]);
	}
	return broken;
}
